// Regenerates src/generated/local-test-usd8.ts from the forge build of contracts/src/LocalTestUSD8.sol.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const artifact = JSON.parse(readFileSync(join(root, 'contracts/out/LocalTestUSD8.sol/LocalTestUSD8.json'), 'utf8'));
mkdirSync(join(root, 'src/generated'), { recursive: true });
writeFileSync(
  join(root, 'src/generated/local-test-usd8.ts'),
  '// Generated by npm run build:token (forge build of contracts/src/LocalTestUSD8.sol, solc 0.8.24, optimizer 200, no metadata). Do not edit.\n' +
    `export const LOCAL_TEST_USD8_ABI = ${JSON.stringify(artifact.abi)} as const;\n` +
    `export const LOCAL_TEST_USD8_BYTECODE = ${JSON.stringify(artifact.bytecode.object)} as const;\n`,
);
console.log('wrote src/generated/local-test-usd8.ts');
